     1	/* ============================ Tự khám phá: camera bám đuôi ============================
     2	   Camera đích = pos − forward·back + up·up; trễ mũ theo CONFIG.explore.chase.lag; nhìn vào pos + forward·30. */
     3	import * as THREE from 'three';
     4	import { CONFIG } from '../config';
     5	import type { GliderState } from './flight';
     6	
     7	const K = CONFIG.explore.chase;
     8	const _want = new THREE.Vector3();
     9	
    10	export function exChase(camera: THREE.PerspectiveCamera, target: THREE.Vector3, s: GliderState, dt: number, snap = false): void {
    11	  const fx = Math.cos(s.yaw), fz = -Math.sin(s.yaw);
    12	  _want.set(s.pos.x - fx * K.back, s.pos.y + K.up, s.pos.z - fz * K.back);
    13	  if (snap) camera.position.copy(_want);
    14	  else camera.position.lerp(_want, 1 - Math.exp(-dt / K.lag));
    15	  target.set(s.pos.x + fx * 30, s.pos.y, s.pos.z + fz * 30);
    16	  camera.lookAt(target);
    17	}
---FLIGHT
     1	/* ============================ Tự khám phá: mô hình bay dù lượn ============================
     2	   Thuần toán học, không đụng cảnh. Hướng bay (cos yaw, 0, −sin yaw), cùng quy ước với `walk` trong views/camera.ts:
     3	   yaw tăng là rẽ trái, bank > 0 là nghiêng trái. Mọi thông số ở CONFIG.explore. */
     4	import * as THREE from 'three';
     5	import { CONFIG } from '../config';
     6	
     7	const C = CONFIG.explore;
     8	
     9	export interface GliderState { pos: THREE.Vector3; yaw: number; bank: number }
    10	export interface GliderInput { turn: -1 | 0 | 1; climb: -1 | 0 | 1 }
    11	
    12	/* Trạng thái ban đầu tại điểm cất cánh */
    13	export function exCreate(): GliderState {
    14	  return { pos: new THREE.Vector3(C.takeoff[0], C.takeoff[1], C.takeoff[2]), yaw: C.takeoffYaw, bank: 0 };
    15	}
    16	
    17	const wrapPi = (a: number) => Math.atan2(Math.sin(a), Math.cos(a));
    18	
    19	/* Lái về tâm khung khi sát mép: trả hướng rẽ hiệu lực (−1..1) thay cho phím người chơi */
    20	function exTurnEff(s: GliderState, turn: number): number {
    21	  const b = C.bounds, m = C.returnMargin;
    22	  const d = Math.min(s.pos.x - b.x0, b.x1 - s.pos.x, s.pos.z - b.z0, b.z1 - s.pos.z);   // khoảng cách ngắn nhất tới mép khung
    23	  if (d >= m) return turn;
    24	  const tx = (b.x0 + b.x1) / 2 - s.pos.x, tz = (b.z0 + b.z1) / 2 - s.pos.z, tl = Math.hypot(tx, tz) || 1;
    25	  const dot = (Math.cos(s.yaw) * tx - Math.sin(s.yaw) * tz) / tl;   // hướng bay · hướng tới tâm
    26	  if (dot >= 0.3) return turn;   // đang bay vào trong: giữ phím người chơi
    27	  const delta = wrapPi(Math.atan2(-tz, tx) - s.yaw);   // yaw hướng tâm − yaw hiện tại
    28	  const sg = delta >= 0 ? 1 : -1;
    29	  if (d <= 0.25 * m) return sg;
    30	  const w = 1 - d / m;
    31	  return turn + (sg - turn) * w;
    32	}
    33	
    34	/* Một bước mô phỏng: không cấp phát */
    35	export function exStep(s: GliderState, inp: GliderInput, dt: number): void {
    36	  const turn = exTurnEff(s, inp.turn);
    37	  s.bank += (turn * C.bankMax - s.bank) * Math.min(1, C.bankRate * dt);
    38	  s.yaw += C.turnRate * (s.bank / C.bankMax) * dt;
    39	  s.pos.x += Math.cos(s.yaw) * C.speed * dt;
    40	  s.pos.z -= Math.sin(s.yaw) * C.speed * dt;
    41	  s.pos.y = Math.min(C.ceiling, Math.max(C.floor, s.pos.y + inp.climb * C.climbRate * dt));
    42	  const b = C.bounds;   // kẹp cứng: không bao giờ vượt khung
    43	  s.pos.x = Math.min(b.x1, Math.max(b.x0, s.pos.x));
    44	  s.pos.z = Math.min(b.z1, Math.max(b.z0, s.pos.z));
    45	}
    46	
    47	/* Phím giữ → đầu vào lái: A/← trái, D/→ phải, W/↑ lên, S/↓ xuống; hai phím ngược nhau triệt tiêu */
    48	export function exInputFromKeys(keys: Set<string>): GliderInput {
    49	  const turn = (keys.has('a') || keys.has('arrowleft') ? 1 : 0) - (keys.has('d') || keys.has('arrowright') ? 1 : 0);
    50	  const climb = (keys.has('w') || keys.has('arrowup') ? 1 : 0) - (keys.has('s') || keys.has('arrowdown') ? 1 : 0);
    51	  return { turn: turn as -1 | 0 | 1, climb: climb as -1 | 0 | 1 };
    52	}

